import unittest
from rosterkit.notices import absence_notice
from rosterkit.models import Student, Mark
from rosterkit.errors import ProjectError
from datetime import date

S = Student("1", "Doe", "Jo", "A")

def mark(sid, day, status):
    return Mark(sid, date(2026, 9, day), status)

class NoticeTests(unittest.TestCase):
    def test_notice(self):
        m = [mark("1", 5, "absent"), mark("1", 2, "absent")]
        want = "Jo Doe missed 2 day(s): 2026-09-02, 2026-09-05."
        self.assertEqual(absence_notice(S, m), want)

    def test_other_student(self):
        with self.assertRaises(ProjectError):
            absence_notice(S, [mark("2", 2, "absent")])

    def test_no_absences(self):
        with self.assertRaises(ProjectError):
            absence_notice(S, [mark("1", 2, "present")])
